const SEARCH="https://scon.stj.jus.br/SCON/SearchBRS";
const UA="Lex.HomoSapiens/1.1";
const CKAN="https://dadosabertos.web.stj.jus.br/api/3/action/package_show";
const DATASETS=[
  "espelhos-de-acordaos-corte-especial",
  "espelhos-de-acordaos-primeira-secao",
  "espelhos-de-acordaos-segunda-secao",
  "espelhos-de-acordaos-terceira-secao",
  "espelhos-de-acordaos-primeira-turma",
  "espelhos-de-acordaos-segunda-turma",
  "espelhos-de-acordaos-terceira-turma",
  "espelhos-de-acordaos-quarta-turma",
  "espelhos-de-acordaos-quinta-turma",
  "espelhos-de-acordaos-sexta-turma"
];
const cache=new Map();
const ttl=10*60*1000;
const norm=s=>String(s||"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase();
const words=q=>norm(q).split(/[^a-z0-9]+/).filter(x=>x.length>2 && !new Set(["para","com","dos","das","uma","por","que","sem","sobre","entre","como","nos","nas"]).has(x));
async function fetchText(url,accept="application/json"){const c=new AbortController(),t=setTimeout(()=>c.abort(),15000);try{const r=await fetch(url,{headers:{"user-agent":UA,accept},signal:c.signal,redirect:"follow"});if(!r.ok)throw new Error(`HTTP ${r.status}`);return {text:await r.text(),url:r.url||url,status:r.status};}finally{clearTimeout(t)}}
function pack(q,results,evidence,coverage="stj_open_data_recent"){return {status:results.length?"ok":"source_insufficient",service:"lex-jurisprudencia-router",version:"1.1.0",tribunal:"stj",query:q,result_count:results.length,results,evidence,sources_used:results.length?["stj_dados_abertos"]:[],integrity:{official:results.length,synthetic:0,source_urls_present:results.filter(x=>x.source_url).length},warnings:results.length?["Fonte oficial de dados abertos do STJ. O recorte consulta os recursos JSON recentes publicados por órgão julgador; revisão humana permanece obrigatória."]:["Nenhum resultado verificável foi extraído do recorte recente de dados abertos; nenhum precedente foi inventado."],coverage,human_review_required:true,no_invention_policy:true}}
async function packageInfo(id){const key=`pkg:${id}`,hit=cache.get(key);if(hit&&Date.now()-hit.at<ttl)return hit.v;const r=await fetchText(`${CKAN}?id=${encodeURIComponent(id)}`);const j=JSON.parse(r.text);if(!j.success||!j.result)throw new Error("ckan_package_unavailable");cache.set(key,{at:Date.now(),v:j.result});return j.result}
function latestJsonResources(pkg,n=2){return (pkg.resources||[]).filter(r=>String(r.format||"").toUpperCase()==="JSON" && /\.json(?:$|\?)/i.test(String(r.url||""))).sort((a,b)=>String(b.name||b.last_modified||b.created||"").localeCompare(String(a.name||a.last_modified||a.created||""))).slice(0,n)}
async function resourceData(res){const key=`res:${res.id||res.url}`,hit=cache.get(key);if(hit&&Date.now()-hit.at<ttl)return hit.v;const r=await fetchText(res.url);const j=JSON.parse(r.text);const arr=Array.isArray(j)?j:(Array.isArray(j?.result)?j.result:[]);cache.set(key,{at:Date.now(),v:{arr,url:r.url,status:r.status}});return {arr,url:r.url,status:r.status}}
function scoreDoc(doc,toks){const blob=norm([doc.ementa,doc.teseJuridica,doc.tema,doc.informacoesComplementares,doc.termosAuxiliares,doc.decisao,doc.siglaClasse,doc.descricaoClasse].filter(Boolean).join(" "));if(!blob)return 0;let s=0;for(const t of toks){if(blob.includes(t))s+=1}return s}
function resultFrom(doc,url,score){const proc=[doc.siglaClasse,doc.numeroProcesso].filter(Boolean).join(" ").trim();return {tribunal:"STJ",tipo:doc.tipoDeDecisao||"ACÓRDÃO",processo:proc||doc.numeroRegistro||null,numero_registro:doc.numeroRegistro||null,orgao_julgador:doc.nomeOrgaoJulgador||null,relator:doc.ministroRelator||null,data_decisao:doc.dataDecisao||null,data_publicacao:doc.dataPublicacao||null,title:proc||`STJ ${doc.nomeOrgaoJulgador||""}`.trim(),content:String(doc.ementa||doc.teseJuridica||doc.decisao||"").slice(0,7000),tese_juridica:doc.teseJuridica||null,tema:doc.tema||null,source:"stj_dados_abertos",source_url:url,is_official:true,is_synthetic:false,match_score:score,id:doc.id||null}}
async function searchOpenData(q,limit){const toks=words(q);if(!toks.length)return pack(q,[],[],"query_too_broad");const evidence=[],found=[];await Promise.all(DATASETS.map(async id=>{try{const pkg=await packageInfo(id),resources=latestJsonResources(pkg,2);for(const res of resources){const d=await resourceData(res);evidence.push({source:"stj_dados_abertos",dataset:id,resource:res.name||res.id,url:d.url,status:"ok",http_status:d.status});for(const doc of d.arr){const s=scoreDoc(doc,toks);if(s>0)found.push({doc,url:d.url,score:s})}}}catch(e){evidence.push({source:"stj_dados_abertos",dataset:id,status:"error",message:String(e?.message||e).slice(0,180)})}}));
const seen=new Set(),out=[];found.sort((a,b)=>b.score-a.score || String(b.doc.dataDecisao||"").localeCompare(String(a.doc.dataDecisao||"")));for(const x of found){const k=x.doc.id||`${x.doc.numeroRegistro}|${x.doc.numeroProcesso}`;if(seen.has(k))continue;seen.add(k);out.push(resultFrom(x.doc,x.url,x.score));if(out.length>=Math.max(1,Math.min(Number(limit)||10,20)))break}return pack(q,out,evidence,"stj_open_data_recent_2_resources_per_dataset")}
async function sconFallback(q,limit){try{const p=new URLSearchParams({b:"ACOR",livre:q,p:"true",operador:"E"}),r=await fetchText(`${SEARCH}?${p}`,"text/html"),txt=r.text.replace(/<[^>]+>/g," ").replace(/\s+/g," "),re=/\b(?:REsp|AREsp|RMS|RHC|HC|CC|EREsp)\s*(?:n[.ºo°]\s*)?([\d.]+(?:\/[A-Z]{2})?)\b/gi,seen=new Set(),results=[];for(const m of txt.matchAll(re)){const proc=m[0].replace(/\s+/g," ").trim();if(seen.has(proc))continue;seen.add(proc);results.push({tribunal:"STJ",tipo:"acordao",processo:proc,title:proc,content:txt.slice(Math.max(0,m.index-300),m.index+2500),source:"stj_scon",source_url:"https://scon.stj.jus.br/SCON/",is_official:true,is_synthetic:false});if(results.length>=Math.max(1,Math.min(Number(limit)||10,20)))break}return pack(q,results,[{source:"stj_scon",url:r.url,status:"ok",http_status:r.status}],results.length?"stj_scon":"insufficient")}catch(e){return pack(q,[],[{source:"stj_scon",status:"error",message:String(e?.message||e).slice(0,180)}],"source_error")}}
export async function searchStjJurisprudence(query,limit=10){const q=String(query||"").trim();if(!q)return pack(q,[],[],"query_required");try{const open=await searchOpenData(q,limit);if(open.result_count)return open;const fallback=await sconFallback(q,limit);fallback.evidence=[...(open.evidence||[]),...(fallback.evidence||[])];return fallback;}catch(e){return {status:"source_unavailable",service:"lex-jurisprudencia-router",version:"1.1.0",tribunal:"stj",query:q,result_count:0,results:[],evidence:[{source:"stj_dados_abertos",status:"error",message:String(e?.message||e).slice(0,200)}],sources_used:[],integrity:{official:0,synthetic:0,source_urls_present:0},warnings:["Fonte oficial do STJ indisponível; nenhum precedente foi inventado."],coverage:"source_error",human_review_required:true,no_invention_policy:true}}

}
